  if (decodedOrError.error !== null) {
    return newDeserializationError<Uint8Array>(
      decodedOrError.error
    );
  }

  return new AasCommon.Either<Uint8Array, DeserializationError>(
    decodedOrError.mustValue(),
    null
  );
